INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q65159662', 'youngest Toba eruption', 'The Toba eruption (also called the Toba supereruption and the Youngest Toba eruption) was a large volcanic eruption that occurred around 74,000 years ago during the Late Pleistocene, at the site of present-day Lake Toba in Sumatra, Indonesia. It was the last in a series of at least four caldera-forming eruptions there, the earlier known caldera having formed about 1.2 million years ago.', -71860, NULL, NULL, NULL, NULL, NULL, 'millennium', '72nd millennium BCE', 55, 'https://en.wikipedia.org/wiki/Youngest_Toba_eruption'),
  ('Q16957926', 'Chola invasion of Srivijaya', 'In 1025 AD, the Chola Emperor Rajendra I launched naval invasions on Srivijaya in Maritime Southeast Asia, leading to the fall of the Sailendra dynasty of Srivijaya. Rajendra''s overseas expedition against Srivijaya was a unique event in India''s history and its otherwise peaceful relations with the states of Southeast Asia.', 1025, NULL, NULL, NULL, NULL, NULL, 'year', '1025', 48, 'https://en.wikipedia.org/wiki/Chola_invasion_of_Srivijaya'),
  ('Q2535354', '1257 Samalas eruption', 'In 1257, a catastrophic eruption occurred at Samalas, a volcano on the Indonesian island of Lombok. The event had a probable Volcanic Explosivity Index of 7, making it one of the largest volcanic eruptions during the Holocene epoch.', 1257, NULL, NULL, NULL, NULL, NULL, 'year', '1257', 53, 'https://en.wikipedia.org/wiki/1257_Samalas_eruption'),
  ('Q698226', 'Dutch East Indies campaign', 'The Dutch East Indies campaign of 1941–1942 was the conquest of the Dutch East Indies (present-day Indonesia) by forces of the Empire of Japan in the early days of the Pacific campaign of World War II. Allied forces attempted unsuccessfully to defend the islands. The East Indies were targeted by the Japanese for their rich oil resources which would become a vital asset during the war.', 1941, 12, 8, 1942, 3, 9, 'day', '8 December 1941 – 9 March 1942', 61, 'https://en.wikipedia.org/wiki/Dutch_East_Indies_campaign'),
  ('Q610048', 'Battle of Balikpapan', 'The First Battle of Balikpapan took place on 23–25 January 1942, off the major oil-producing town and port of Balikpapan, on Borneo, in the Netherlands East Indies. After capturing mostly-destroyed oilfields at Tarakan, Japanese forces sent an ultimatum to the Dutch that they would be executed if they destroyed the oilfields there, to no avail.', 1942, 1, 23, 1942, 1, 24, 'day', '23 January 1942 – 24 January 1942', 53, 'https://en.wikipedia.org/wiki/Battle_of_Balikpapan_(1942)'),
  ('Q1440764', 'Battle of Timor', 'The Battle of Timor occurred in Portuguese Timor and Dutch Timor during the Second World War. Japanese forces invaded the island on 19 February 1942 and were resisted by a small, under-equipped force of Allied military personnel—known as Sparrow Force—predominantly from Australia, the United Kingdom, and the Dutch East Indies.', 1942, 2, 19, 1943, 2, 10, 'day', '19 February 1942 – 10 February 1943', 57, 'https://en.wikipedia.org/wiki/Battle_of_Timor'),
  ('Q1536686', 'Battle of Sunda Strait', 'The Battle of Sunda Strait was a naval battle which occurred during World War II in the Sunda Strait between the islands of Java, and Sumatra. On the night of 28 February – 1 March 1942, the Australian light cruiser HMAS Perth, American heavy cruiser USS Houston, and Dutch destroyer HNLMS Evertsen faced a major Imperial Japanese Navy (IJN) task force.', 1942, 2, 28, 1942, 3, 1, 'day', '28 February 1942 – 1 March 1942', 58, 'https://en.wikipedia.org/wiki/Battle_of_Sunda_Strait'),
  ('Q2587905', 'Battle of Manado', 'The Battle of Manado took place as part of the Japanese offensive to capture the Dutch East Indies. It occurred at Manado (also spelled Menado) on the Minahasa Peninsula on the northern part of Celebes Island (modern day Sulawesi in Indonesia), from 11–12 January 1942.', 1942, 1, 11, 1942, 1, 12, 'day', '11 January 1942 – 12 January 1942', 47, 'https://en.wikipedia.org/wiki/Battle_of_Manado'),
  ('Q2889417', 'Battle of Morotai', 'The Battle of Morotai, part of the Pacific War, began on 15 September 1944, and continued until the end of the war in August 1945. The fighting started when United States and Australian forces landed on the southwest corner of Morotai, a small island in the Netherlands East Indies (NEI), which the Allies needed as a base to support the liberation of the Philippines later that year.', 1944, 9, 15, 1944, 10, 4, 'day', '15 September 1944 – 4 October 1944', 51, 'https://en.wikipedia.org/wiki/Battle_of_Morotai'),
  ('Q26496', 'Battle of Surabaya', 'The Battle of Surabaya (Javanese: ꦦꦺꦂꦠꦺꦩ꧀ꦥꦸꦫꦤ꧀ ꦯꦸꦫꦧꦪ; Indonesian: Pertempuran Surabaya) was a major battle in the Indonesian National Revolution fought between regular infantry and militia of the Indonesian nationalist movement and British and British Indian troops against the re-imposition of Dutch colonial rule. The peak of the battle was in November 1945, and was the largest single battle of the revolution and became a national symbol of Indonesian resistance.', 1945, 10, 27, 1945, 11, 20, 'day', '27 October 1945 – 20 November 1945', 56, 'https://en.wikipedia.org/wiki/Battle_of_Surabaya'),
  ('Q1332160', 'Indonesian National Revolution', 'The Indonesian National Revolution (Indonesian: Revolusi Nasional Indonesia), also known as the Indonesian War of Independence, was an armed conflict and diplomatic struggle between the Republic of Indonesia and the Dutch Empire and an internal social revolution during postwar and postcolonial Indonesia. It took place between Indonesia''s declaration of independence in 1945 and the Netherlands'' transfer of sovereignty over the Dutch East Indies to the Republic of the United States of Indonesia at the end of 1949.', 1945, 8, 17, 1949, 12, 27, 'day', '17 August 1945 – 27 December 1949', 73, 'https://en.wikipedia.org/wiki/Indonesian_National_Revolution'),
  ('Q1661772', 'Proclamation of Indonesian Independence', 'The Proclamation of Indonesian Independence (Indonesian: Proklamasi Kemerdekaan Indonesia, or simply Proklamasi) was read at 10:00 Tokyo Standard Time on Friday, 17 August 1945 in Jakarta. The declaration marked the start of the diplomatic and armed resistance of the Indonesian National Revolution, fighting against the forces of the Netherlands and pro-Dutch civilians, until the latter officially acknowledged Indonesia''s independence in 1949.', 1945, 8, 17, NULL, NULL, NULL, 'day', '17 August 1945', 63, 'https://en.wikipedia.org/wiki/Proclamation_of_Indonesian_Independence'),
  ('Q2598930', 'Battle of Tarakan', 'The Battle of Tarakan was an engagement fought between Allied and Japanese forces on the island of Tarakan off Borneo during May and June 1945. It formed the first stage in the World War II Borneo campaign.', 1945, NULL, NULL, 1945, 6, 21, 'year', '1945', 51, 'https://en.wikipedia.org/wiki/Battle_of_Tarakan_(1945)'),
  ('Q4271928', 'Battle of Balikpapan', 'The Battle of Balikpapan was the concluding stage of Operation Oboe, the campaign to liberate Japanese-held British and Dutch Borneo. The landings took place on 1 July 1945.', 1945, 7, 1, NULL, NULL, NULL, 'day', '1 July 1945', 47, 'https://en.wikipedia.org/wiki/Battle_of_Balikpapan_(1945)'),
  ('Q799299', 'crushing The Rebellions of 1965–1966', 'From October 1965 to March 1966, a series of large-scale killings and civil unrest primarily targeting members and supposed sympathizers of the Communist Party of Indonesia (PKI) took place in Indonesia. Other affected groups included alleged communist sympathisers, Gerwani women, trade unionists, ethnic Javanese Abangan, ethnic Chinese, atheists and other non-Muslims, and leftists in general.', 1965, 10, NULL, 1966, NULL, NULL, 'month', 'October 1965 – 1966', 65, 'https://en.wikipedia.org/wiki/Indonesian_mass_killings_of_1965%E2%80%9366'),
  ('Q497163', 'New Order', 'The New Order (Indonesian: Orde Baru, abbreviated Orba) was the regime of the second Indonesian President Suharto from his rise to power in 1966 until his resignation in 1998. Suharto coined the term upon his accession and used it to contrast his presidency with that of his predecessor Sukarno (retroactively dubbed the "Old Order" or Orde Lama).', 1966, NULL, NULL, 1998, NULL, NULL, 'year', '1966–1998', 57, 'https://en.wikipedia.org/wiki/New_Order_(Indonesia)'),
  ('Q2665403', 'Indonesian occupation of East Timor', 'The Indonesian occupation of East Timor began in December 1975 and lasted until October 1999. After centuries of Portuguese colonial rule in East Timor, the 1974 Carnation Revolution in Portugal led to the decolonisation of its former colonies, creating instability in East Timor and leaving its future uncertain.', 1975, 12, 7, 1999, 10, 31, 'day', '7 December 1975 – 31 October 1999', 57, 'https://en.wikipedia.org/wiki/Indonesian_occupation_of_East_Timor'),
  ('Q28136238', 'East Timor genocide', 'The East Timor genocide refers to the campaign of systematic killings, repression and state terrorism against the East Timorese people by Indonesia''s New Order regime between 1975 and 1999, during the invasion and subsequent occupation of East Timor. The Indonesian military framed their counter-insurgency operations as "pacification" and "anti-communist stabilisation" while operating with total impunity and engaging in a large-scale extermination of the East Timor''s population, including mass killings, forced displacement, starvation, and the destruction of East Timor''s social and political…', 1975, NULL, NULL, 1999, NULL, NULL, 'year', '1975–1999', 50, 'https://en.wikipedia.org/wiki/East_Timor_genocide'),
  ('Q5524465', 'Garuda Indonesia Flight 035', 'Garuda Indonesia Flight 035 was a domestic Garuda Indonesia flight that struck a pylon and crashed on approach to Medan-Polonia Airport on 4 April 1987. Out of the 45 passengers and crew on board, 23 were killed in the accident.', 1987, 4, 4, NULL, NULL, NULL, 'day', '4 April 1987', 48, 'https://en.wikipedia.org/wiki/Garuda_Indonesia_Flight_035'),
  ('Q3274581', 'Garuda Indonesia Flight 865', 'Garuda Indonesia Flight 865 was a scheduled international flight from Fukuoka, Japan, to Jakarta, Indonesia via Bali, Indonesia. On 13 June 1996, Flight 865 crashed on takeoff from runway 16 at Fukuoka Airport.', 1996, 6, 13, NULL, NULL, NULL, 'day', '13 June 1996', 51, 'https://en.wikipedia.org/wiki/Garuda_Indonesia_Flight_865'),
  ('Q1272213', 'SilkAir Flight 185', 'SilkAir Flight 185 was a scheduled international passenger flight operated by a Boeing 737-300 from Soekarno–Hatta International Airport in Jakarta, Indonesia to Changi Airport in Singapore that crashed into the Musi River near Palembang, Sumatra, on 19 December 1997, killing all 97 passengers and 7 crew members on board. The investigation into the cause of the crash was led by investigators from the National Transportation Safety Committee (NTSC), who were joined by the National Transportation Safety Board (NTSB).', 1997, 12, 19, NULL, NULL, NULL, 'day', '19 December 1997', 64, 'https://en.wikipedia.org/wiki/SilkAir_Flight_185'),
  ('Q3503541', 'Garuda Indonesia Flight 152', 'Garuda Indonesia Flight 152 was a scheduled domestic flight operated by Garuda Indonesia from Soekarno–Hatta International Airport, Tangerang, Indonesia, to Polonia International Airport, Medan, Indonesia. On 26 September 1997, the Airbus A300 flying the route crashed into mountainous woodlands near the village of Buah Nabar, Sibolangit, killing all 222 passengers and 12 crew members on board.', 1997, 9, 26, NULL, NULL, NULL, 'day', '26 September 1997', 60, 'https://en.wikipedia.org/wiki/Garuda_Indonesia_Flight_152'),
  ('Q2749287', 'May 1998 riots of Indonesia', 'The May 1998 Indonesia riots (Indonesian: Kerusuhan Mei 1998), also known colloquially as the 1998 tragedy (Tragedi 1998) or simply the 98 event (Peristiwa 98), were incidents of riots and civil unrest in Indonesia, many of which targeted the country''s ethnic Chinese population. The events were mainly in the cities of Jakarta, Medan, Surakarta, Palembang, and Surabaya with smaller incidents in other parts of Indonesia.', 1998, 5, 4, 1998, 5, 15, 'day', '4 May 1998 – 15 May 1998', 53, 'https://en.wikipedia.org/wiki/May_1998_Indonesia_riots'),
  ('Q86584', '2002 Bali bombings', 'On 12 October 2002, three terrorist attacks took place in the tourist district of Kuta on the Indonesian island of Bali. 2 suicide bombings occurred in two popular nightspots in Kuta Beach, the Sari Club and Paddy''s Pub, killing a total of 202 people including 151 Western tourists from Australia and Europe as well as 38 local Indonesian residents living or working in businesses or homes around the nightclubs.', 2002, 10, 12, 2002, NULL, NULL, 'day', '2002', 68, 'https://en.wikipedia.org/wiki/2002_Bali_bombings'),
  ('Q3608354', 'Garuda Indonesia Flight 421', 'Garuda Indonesia Flight 421 was a scheduled domestic flight operated by Indonesian flag carrier Garuda Indonesia travelling about 625 km (388 mi; 337 nmi) from Ampenan to Yogyakarta utilizing a Boeing 737-300. On 16 January 2002, the flight encountered severe thunderstorm activity during approach to its destination, suffered flameout in both engines, and ditched in a shallow river, resulting in one fatality and several injuries.', 2002, 1, 16, NULL, NULL, NULL, 'day', '16 January 2002', 53, 'https://en.wikipedia.org/wiki/Garuda_Indonesia_Flight_421'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q569255', '2005 Bali bombings', 'Terrorist attacks occurred on 1 October 2005 in Bali, Indonesia. Bombs were detonated at two sites in Jimbaran Beach resort and in Kuta 30 km (19 mi) away, both in south Bali.', 2005, 10, 1, NULL, NULL, NULL, 'day', '1 October 2005', 56, 'https://en.wikipedia.org/wiki/2005_Bali_bombings'),
  ('Q746785', 'Mandala Airlines Flight 091', 'Mandala Airlines Flight 091 (RI091/MDL091) was a scheduled domestic passenger flight from Medan to Jakarta, operated by Mandala Airlines with a Boeing 737-200. On 5 September 2005 at 10:15 a.m.', 2005, 9, 5, NULL, NULL, NULL, 'day', '5 September 2005', 60, 'https://en.wikipedia.org/wiki/Mandala_Airlines_Flight_091'),
  ('Q939106', '2005 Sumatra earthquake', 'On 28 March 2005, at 23:09:37 WIB, a Mw 8.6–8.7 earthquake struck the Banyak Islands, located off the coast of Aceh, Indonesia. It was the most powerful earthquake globally since the 2004 Indian Ocean earthquake three months prior, and is tied with the 2012 Indian Ocean, 1957 Andreanof Islands, 1950 Assam–Tibet and 1946 Aleutian Islands earthquakes as the tenth-largest earthquake ever recorded by seismometers.', 2005, 3, 28, NULL, NULL, NULL, 'day', '28 March 2005', 55, 'https://en.wikipedia.org/wiki/2005_Nias%E2%80%93Simeulue_earthquake'),
  ('Q867691', 'May 2006 Java earthquake', 'The 2006 Yogyakarta earthquake (also known as the Bantul earthquake) occurred at 05:53 local time on 27 May with a moment magnitude of 6.4 and a maximum MSK intensity of VIII (Damaging) in the Yogyakarta region of Java, Indonesia. Several factors led to a disproportionate amount of damage and number of casualties for the size of the shock, with more than 5,700 dead, tens of thousands injured, and financial losses of Rp 29.1 trillion ($3.1 billion).', 2006, 5, 27, NULL, NULL, NULL, 'day', '27 May 2006', 65, 'https://en.wikipedia.org/wiki/2006_Yogyakarta_earthquake'),
  ('Q1348976', 'July 2006 Java earthquake', 'An earthquake occurred on July 17, 2006, at 15:19:27 local time along a subduction zone off the coast of west and central Java, a large and densely populated island in the Indonesian archipelago. The shock had a moment magnitude of 7.7 and a maximum perceived intensity of IV (Light) in Jakarta, the capital and largest city of Indonesia.', 2006, 7, 17, NULL, NULL, NULL, 'day', '17 July 2006', 56, 'https://en.wikipedia.org/wiki/2006_Pangandaran_earthquake_and_tsunami'),
  ('Q250439', 'Adam Air Flight 574', 'Adam Air Flight 574 was a scheduled domestic passenger flight operated by an Adam Air Boeing 737-400 between the Indonesian cities of Jakarta, Surabaya, and Manado that crashed into the Makassar Strait near Polewali in Sulawesi on 1 January 2007. All 102 people on board were killed, making it the deadliest aviation accident involving a 737-400.', 2007, 1, 1, NULL, NULL, NULL, 'day', '1 January 2007', 69, 'https://en.wikipedia.org/wiki/Adam_Air_Flight_574'),
  ('Q1494794', 'Garuda Indonesia Flight 200', 'Garuda Indonesia Flight 200 (GA200/GIA200) was a scheduled domestic passenger flight of a Boeing 737-400 operated by Garuda Indonesia between Jakarta and Yogyakarta, Indonesia. The aircraft overran the runway, crashed into a rice field and burst into flames while landing at Adisucipto International Airport on 7 March 2007.', 2007, 3, 7, NULL, NULL, NULL, 'day', '7 March 2007', 57, 'https://en.wikipedia.org/wiki/Garuda_Indonesia_Flight_200'),
  ('Q745411', '2009 West Java earthquake', 'An earthquake occurred on September 2, 2009, at 14:55:01 local time in West Java, Indonesia. The magnitude 7.0 earthquake killed at least 81 people, injured over 1,297, and displaced over 210,000 (including more than 140,000 in Tasikmalaya regency).', 2009, 9, 2, NULL, NULL, NULL, 'day', '2 September 2009', 48, 'https://en.wikipedia.org/wiki/2009_West_Java_earthquake'),
  ('Q1049092', 'October 2010 Sumatra earthquake and tsunami', 'The 2010 Mentawai earthquake occurred with a moment magnitude of 7.8 on 25 October off the western coast of Sumatra at 21:42 local time (14:42 UTC). The earthquake occurred on the same subduction zone that produced the 2004 Indian Ocean earthquake.', 2010, 10, 25, NULL, NULL, NULL, 'day', '25 October 2010', 57, 'https://en.wikipedia.org/wiki/2010_Mentawai_earthquake_and_tsunami'),
  ('Q1135895', 'Qantas Flight 32', 'Qantas Flight 32 was a regularly scheduled passenger flight from London to Sydney via Singapore. On 4 November 2010, the Airbus A380 operating the route suffered an uncontained failure in one of its four Rolls-Royce Trent 900 engines.', 2010, 11, 4, NULL, NULL, NULL, 'day', '4 November 2010', 60, 'https://en.wikipedia.org/wiki/Qantas_Flight_32'),
  ('Q2523832', 'Merpati Nusantara Airlines Flight 8968', 'Merpati Nusantara Airlines Flight 8968 (MZ8968/MNA8968) was a passenger flight which crashed off the coast of the Indonesian province of West Papua on 7 May 2011. The aircraft involved, a Xian MA60, was operating Merpati Nusantara Airlines'' scheduled domestic service from Sorong to Kaimana, both in West Papua.', 2011, 5, 7, NULL, NULL, NULL, 'day', '7 May 2011', 51, 'https://en.wikipedia.org/wiki/Merpati_Nusantara_Airlines_Flight_8968'),
  ('Q383991', '2012 Indian Ocean earthquakes', 'The 2012 Indian Ocean earthquakes were magnitude 8.6 and 8.2 Mw undersea earthquakes that struck near the Indonesian province of Aceh on 11 April at 15:38 local time. Initially, authorities feared that the initial earthquake would cause a tsunami and warnings were issued across the Indian Ocean; however, these warnings were subsequently cancelled.', 2012, 4, 11, NULL, NULL, NULL, 'day', '11 April 2012', 66, 'https://en.wikipedia.org/wiki/2012_Indian_Ocean_earthquakes'),
  ('Q1419491', '2012 Mount Salak Sukhoi Superjet crash', 'On 9 May 2012, Sukhoi Civil Aircraft Flight 36801, a Sukhoi Superjet 100 airliner on a demonstration tour in Indonesia crashed into Mount Salak, in the province of West Java. All 37 passengers and 8 crew on board were killed.', 2012, 5, 9, NULL, NULL, NULL, 'day', '9 May 2012', 57, 'https://en.wikipedia.org/wiki/2012_Mount_Salak_Sukhoi_Superjet_crash'),
  ('Q10903028', 'Lion Air Flight 904', 'Lion Air Flight 904 was a scheduled domestic passenger flight from Husein Sastranegara International Airport in Bandung to Ngurah Rai International Airport in Bali, Indonesia. On 13 April 2013, the Boeing 737-800 operating the flight crashed into water short of the runway while on final approach to land.', 2013, 4, 13, NULL, NULL, NULL, 'day', '13 April 2013', 53, 'https://en.wikipedia.org/wiki/Lion_Air_Flight_904'),
  ('Q20823597', 'Trigana Air Service Flight 267', 'Trigana Air Flight 267 was a scheduled passenger flight from Sentani to Oksibil in the eastern Indonesian province of Papua. On 16 August 2015, the ATR 42 turboprop operating the service crashed on approach in the Bintang highlands region of Oksibil, killing all 49 passengers and 5 crew members.', 2015, 8, 16, NULL, NULL, NULL, 'day', '16 August 2015', 62, 'https://en.wikipedia.org/wiki/Trigana_Air_Flight_267'),
  ('Q22067779', '2016 Jakarta attacks', 'On 14 January 2016, multiple explosions and gunfire were reported near the Sarinah shopping mall in central Jakarta, Indonesia, at the intersection of Jalan Kyai Haji Wahid Hasyim and Jalan MH Thamrin. One blast went off in a Burger King restaurant outside the mall.', 2016, 1, 14, NULL, NULL, NULL, 'day', '14 January 2016', 61, 'https://en.wikipedia.org/wiki/2016_Jakarta_attacks'),
  ('Q43946258', '2017–2018 eruptions of Mount Agung', 'Mount Agung, a volcano on the island of Bali in Indonesia, erupted five times in late November 2017, causing thousands to evacuate, disrupting air travel and causing environmental damage. As of 27 November 2017, the alert level was at its highest and evacuation orders were in place.', 2017, NULL, NULL, NULL, NULL, NULL, 'year', '2017', 51, 'https://en.wikipedia.org/wiki/2017%E2%80%932019_eruptions_of_Mount_Agung'),
  ('Q55808122', 'July 2018 Lombok earthquake', 'A Mw 6.4 earthquake struck the island of Lombok on the morning of 29 July 2018 at a shallow depth of 14 km (8.7 mi). Widespread damage was reported in the area, and authorities confirmed that 20 people were killed in the earthquake while hundreds were injured.', 2018, 7, 29, NULL, NULL, NULL, 'day', '29 July 2018', 55, 'https://en.wikipedia.org/wiki/July_2018_Lombok_earthquake'),
  ('Q55974069', '5 August 2018 Lombok earthquake', 'On 5 August 2018, a destructive and shallow earthquake measuring Mw 6.9 (ML 7.0 according to BMKG) struck the island of Lombok, Indonesia. It was the main shock following its foreshock, a nearby Mw 6.4 earthquake on 29 July.', 2018, 8, 5, NULL, NULL, NULL, 'day', '5 August 2018', 57, 'https://en.wikipedia.org/wiki/5_August_2018_Lombok_earthquake'),
  ('Q56768333', '2018 Sulawesi earthquake and tsunami', 'On 28 September 2018, a shallow, large earthquake struck in the neck of the Minahasa Peninsula, Indonesia, with its epicentre located in the mountainous Donggala Regency, Central Sulawesi. The magnitude 7.5–7.6 quake was located 70 km (43 mi) away from the provincial capital Palu and was felt as far away as Samarinda on East Kalimantan and also in Tawau, Malaysia.', 2018, 9, 28, NULL, NULL, NULL, 'day', '28 September 2018', 68, 'https://en.wikipedia.org/wiki/2018_Sulawesi_earthquake_and_tsunami'),
  ('Q60042839', '2018 Sunda Strait tsunami', 'The 2018 Sunda Strait tsunami (Indonesian: Tsunami Selat Sunda 2018) occurred on 22 December 2018 at around 21:38 local time after large parts of the southwestern side of Anak Krakatoa collapsed onto its caldera. The landslide spawned a tsunami wave that struck multiple coastal regions in Banten and Lampung, including the tourist destination of Anyer.', 2018, 12, 22, NULL, NULL, NULL, 'day', '22 December 2018', 68, 'https://en.wikipedia.org/wiki/2018_Sunda_Strait_tsunami'),
  ('Q66594425', '2019 Papua and West Papua protests', 'The 2019 Papua protests were a series of protests by Papuans in Indonesia that began on 19 August 2019 and mainly took place across Indonesian Papua region in response to the arrests of 43 Papuan students in Surabaya, East Java for alleged disrespect of the Indonesian flag. Many of the protests involved thousands of participants, and some grew from local protests in Surabaya to demanding an independence referendum for the whole region.', 2019, 8, 19, NULL, NULL, NULL, 'day', '19 August 2019', 50, 'https://en.wikipedia.org/wiki/2019_Papua_protests'),
  ('Q68746792', '2019 Ambon earthquake', 'On 26 September 2019, a strong magnitude 6.5 earthquake struck Seram Island in Maluku, Indonesia, near the provincial capital of Ambon. The earthquake struck at 07:46:44 Eastern Indonesia Time (23:46:44 on 25 September UTC) with a shallow depth of 18 km.', 2019, 9, 25, NULL, NULL, NULL, 'day', '25 September 2019', 52, 'https://en.wikipedia.org/wiki/2019_Ambon_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q104759345', 'Sriwijaya Air Flight 182', 'Sriwijaya Air Flight 182 was a scheduled domestic passenger flight from Jakarta to Pontianak, Indonesia. Just four minutes after departing from Soekarno–Hatta International Airport on 9 January 2021, the Boeing 737-500 entered an upset and crashed into the Java Sea off the Thousand Islands, killing all 62 people on board.', 2021, 1, 9, NULL, NULL, NULL, 'day', '9 January 2021', 70, 'https://en.wikipedia.org/wiki/Sriwijaya_Air_Flight_182'),
  ('Q104828966', '2021 West Sulawesi earthquake', 'A moment magnitude (Mw) 6.2 earthquake struck Majene Regency in West Sulawesi, Indonesia, on 15 January 2021, at 02:28 WITA (18:28 UTC). The reverse faulting shock initiated at 18.0 km (11.2 mi) depth with an epicenter inland, located 32 km (20 mi) south of Mamuju.', 2021, 1, 15, NULL, NULL, NULL, 'day', '15 January 2021', 59, 'https://en.wikipedia.org/wiki/2021_West_Sulawesi_earthquake'),
  ('Q109922209', '2021 Semeru eruption', 'An eruption of Mount Semeru, a volcano in East Java province of the Indonesian island of Java, began on 4 December 2021. The eruption began after heavy precipitation caused the collapse of the lava dome at the summit.', 2021, 12, 4, NULL, NULL, NULL, 'day', '4 December 2021', 56, 'https://en.wikipedia.org/wiki/2021_Semeru_eruption'),
  ('Q111014585', 'West Pasaman earthquake 2022', 'On 25 February 2022 at 08:39 WIB, a moment magnitude (Mw) 6.2 earthquake struck West Sumatra, Indonesia at a depth of 4.0 km (2.5 mi). Preceded by one foreshock and followed by over 200 aftershocks, the mainshock had an epicenter at the foot of Mount Talakmau in Pasaman Regency.', 2022, 2, 25, NULL, NULL, NULL, 'day', '25 February 2022', 56, 'https://en.wikipedia.org/wiki/2022_Sumatra_earthquake'),
  ('Q115322003', '2022 Cianjur earthquake', 'On 21 November 2022, at 13:21 WIB (UTC+07:00), a Mww 5.6 earthquake struck near Cianjur in West Java, Indonesia. The strike-slip earthquake occurred with a focal depth of 11 km (6.8 mi).', 2022, 11, 21, NULL, NULL, NULL, 'day', '21 November 2022', 65, 'https://en.wikipedia.org/wiki/2022_West_Java_earthquake'),
  ('Q123668173', '2023 eruption of Mount Marapi', 'On 3 December 2023, Mount Marapi, a complex volcano on the Indonesian island of Sumatra, erupted, sending ash as high as 3,000 metres (10,000 ft) into the air, and depositing large amounts of volcanic ash in nearby districts. Twenty-four hikers were found dead near the crater of the volcano.', 2023, 12, 3, NULL, NULL, NULL, 'day', '3 December 2023', 48, 'https://en.wikipedia.org/wiki/2023_eruption_of_Mount_Marapi'),
  ('Q132473192', '2025 Indonesian protests', 'Since February 2025, public and student-led anti-government demonstrations have been held throughout several cities in Indonesia. The first wave of protests were launched on 17 February 2025 by the All-Indonesian Students'' Union (BEM SI), together with individual students'' unions.', 2025, 2, 17, 2025, 12, 31, 'day', '17 February 2025 – 31 December 2025', 51, 'https://en.wikipedia.org/wiki/2025%E2%80%932026_Indonesian_protests'),
  ('Q135989908', 'August–September 2025 Indonesian protests', 'On 25 August until early September 2025, several protests took place in Indonesia as part of a larger civil unrest which began in early 2025 over economic frustrations and a proposed hike in housing subsidies for members of parliament. Protesters initially demanded the House of Representatives reverse its subsidy schemes and penalize its members who made insensitive statements, as well as pass the Confiscation of Assets Act for lawmakers convicted of corruption.', 2025, 8, 25, 2025, 9, 9, 'day', '25 August 2025 – 9 September 2025', 52, 'https://en.wikipedia.org/wiki/August_2025_Indonesian_protests'),
  ('Q137801147', '2026 Indonesia Air Transport ATR 42 crash', 'On 17 January 2026, an ATR 42 operated by Indonesia Air Transport crashed while flying from Adisutjipto Airport to Sultan Hasanuddin International Airport in Indonesia. Air traffic control reportedly lost contact with the flight in the South Sulawesi area, and the aircraft was ultimately found to have crashed in the Bulusaraung mountain area.', 2026, 1, 17, NULL, NULL, NULL, 'day', '17 January 2026', 52, 'https://en.wikipedia.org/wiki/2026_Indonesia_Air_Transport_ATR_42_crash'),
  ('Q141072401', '2026 Flores earthquake', 'On 15 August 2026, at 05:58 WITA (UTC+8), a Mw 7.8 earthquake struck off the coast of the island of Flores in East Nusa Tenggara, Indonesia. The earthquake was caused by movement on the Flores back-arc thrust fault located north of the island.', 2026, 8, 14, NULL, NULL, NULL, 'day', '14 August 2026', 57, 'https://en.wikipedia.org/wiki/2026_Flores_earthquake');
